package cn.roomguard;
import android.app.*;import android.os.*;import android.content.*;import android.net.wifi.WifiManager;import android.media.*;import org.json.*;import java.net.*;import java.io.*;import java.util.concurrent.*;
public class AlertService extends Service {
 ScheduledExecutorService executor;PowerManager.WakeLock wake;WifiManager.WifiLock wifi;MediaPlayer player;String activeKey="",lastNotice="";long lastRing=0;volatile boolean stopped=false;
 @Override public void onCreate(){super.onCreate();if(Build.VERSION.SDK_INT>=26){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("monitor","监控连接",NotificationManager.IMPORTANCE_LOW));NotificationChannel alarmChannel=new NotificationChannel("alarm-v2","环境告警",NotificationManager.IMPORTANCE_HIGH);alarmChannel.setSound(null,null);nm.createNotificationChannel(alarmChannel);}startForeground(1,notification("后台监控已启动","正在连接局域网服务器",false));PowerManager pm=(PowerManager)getSystemService(POWER_SERVICE);wake=pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"roomguard:monitor");wake.acquire();WifiManager wm=(WifiManager)getApplicationContext().getSystemService(WIFI_SERVICE);wifi=wm.createWifiLock(WifiManager.WIFI_MODE_FULL_HIGH_PERF,"roomguard:wifi");wifi.acquire();executor=Executors.newSingleThreadScheduledExecutor();executor.scheduleWithFixedDelay(()->poll(),0,2,TimeUnit.SECONDS);}
 Notification notification(String title,String text,boolean alarm){Intent i=new Intent(this,MainActivity.class);int flags=PendingIntent.FLAG_UPDATE_CURRENT;if(Build.VERSION.SDK_INT>=23)flags|=PendingIntent.FLAG_IMMUTABLE;PendingIntent pi=PendingIntent.getActivity(this,0,i,flags);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,alarm?"alarm-v2":"monitor"):new Notification.Builder(this);b.setSmallIcon(cn.roomguard.R.drawable.ic_monitor).setContentTitle(title).setContentText(text).setContentIntent(pi).setOngoing(!alarm).setAutoCancel(alarm);if(alarm)b.setPriority(Notification.PRIORITY_HIGH);return b.build();}
 void poll(){if(stopped)return;HttpURLConnection c=null;try{String base=getSharedPreferences("rg",0).getString("server","");c=(HttpURLConnection)new URL(base+"/api/status").openConnection();c.setConnectTimeout(4000);c.setReadTimeout(4000);c.setInstanceFollowRedirects(false);if(c.getResponseCode()!=200)throw new IOException();ByteArrayOutputStream out=new ByteArrayOutputStream();InputStream in=c.getInputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);if(out.size()>131072)throw new IOException();}in.close();JSONObject json=new JSONObject(out.toString("UTF-8"));String terminal=TerminalIdentity.get(this);HttpURLConnection profileConnection=(HttpURLConnection)new URL(base+"/api/display?terminal_id="+terminal).openConnection();profileConnection.setConnectTimeout(3000);profileConnection.setReadTimeout(3000);JSONObject config;try{ByteArrayOutputStream profileBytes=new ByteArrayOutputStream();InputStream profileInput=profileConnection.getInputStream();while((n=profileInput.read(buf))!=-1){profileBytes.write(buf,0,n);if(profileBytes.size()>16000)throw new IOException();}profileInput.close();config=new JSONObject(profileBytes.toString("UTF-8")).getJSONObject("config");}finally{profileConnection.disconnect();}boolean soundAllowed=config.optBoolean("sound_enabled",true);JSONArray roomFilter=config.optJSONArray("rooms");String floorFilter=config.optString("floor","");JSONArray nodes=json.getJSONArray("nodes");StringBuilder keys=new StringBuilder(),text=new StringBuilder();for(int j=0;j<nodes.length();j++){JSONObject node=nodes.getJSONObject(j),s=node.getJSONObject("state");boolean roomAllowed=roomFilter==null||roomFilter.length()==0;for(int ri=0;roomFilter!=null&&ri<roomFilter.length();ri++)if(roomFilter.optString(ri).equals(node.optString("room")))roomAllowed=true;if(!roomAllowed||(!floorFilter.isEmpty()&&!floorFilter.equals(node.optString("floor"))))continue;if(node.optBoolean("online")&&s.optBoolean("active")&&!s.optBoolean("muted")){keys.append(node.getString("id")).append(s.optString("event_id")).append(s.optJSONArray("reasons")).append(';');text.append(node.getString("room")).append("房间 ").append(s.optBoolean("smoke")?"烟雾／气体 ":"").append(s.optBoolean("flame")?"火焰 ":"").append(s.optBoolean("clearing")?"等待稳定解除 ":"");}}
 if(!soundAllowed)stopTone();String key=keys.toString();NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(!key.isEmpty()){if(!key.equals(activeKey)||SystemClock.elapsedRealtime()-lastRing>=10000){lastRing=SystemClock.elapsedRealtime();if(soundAllowed)ring();else stopTone();nm.notify(2,notification("环境异常告警",text.toString(),true));}}else{nm.cancel(2);stopTone();}activeKey=key;if(!lastNotice.equals("ok")){nm.notify(1,notification("局域网监控运行中","保持后台运行；点击查看房间状态",false));lastNotice="ok";}}
 catch(Exception ex){if(!stopped&&!lastNotice.equals("offline")){((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(1,notification("服务器连接中断","无法获取新告警；请检查Wi-Fi及树莓派",false));lastNotice="offline";}}
 finally{if(c!=null)c.disconnect();}}
 synchronized void ring(){if(stopped)return;stopTone();try{player=MediaPlayer.create(this,android.provider.Settings.System.DEFAULT_ALARM_ALERT_URI);if(player==null)player=MediaPlayer.create(this,android.provider.Settings.System.DEFAULT_NOTIFICATION_URI);if(player!=null){player.setOnCompletionListener(mp->stopTone());player.start();}}catch(Exception e){stopTone();}}
 synchronized void stopTone(){if(player!=null){try{player.release();}catch(Exception ignored){}player=null;}}
 @Override public int onStartCommand(Intent i,int flags,int id){return START_STICKY;}
 @Override public IBinder onBind(Intent i){return null;}
 @Override public void onDestroy(){stopped=true;if(executor!=null)executor.shutdownNow();stopTone();if(wifi!=null&&wifi.isHeld())wifi.release();if(wake!=null&&wake.isHeld())wake.release();((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(2);super.onDestroy();}
}
